import { MakeLogicType, actions, kea, key, listeners, path, props, reducers, selectors } from 'kea'

import { BIField, BIConfig, BIVisualizationNode } from '~/queries/schema/schema-business-intelligence'
import { HogQLQuery } from '~/queries/schema/schema-general'

import { biEditorLogic } from './biEditorLogic'
import { BIEditorView, buildBIFilterOptionsQuery } from './biEditorTypes'
import { biMemberFieldKey } from './biMemberAliases'
import { biSceneLogic } from './biSceneLogic'

interface BIMemberAliasesProps {
    tabId: string
}
// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface biMemberAliasesLogicValues {
    draft: {
        label: string
        value: string | null
    }[]
    field: BIField | null
    query: HogQLQuery | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface biMemberAliasesLogicActions {
    close: () => {
        value: true
    }
    edit: (
        field: BIField,
        aliases: {
            label: string
            value: string | null
        }[]
    ) => {
        aliases: {
            label: string
            value: string | null
        }[]
        field: BIField
    }
    save: () => {
        value: true
    }
    setAlias: (
        value: string | null,
        label: string
    ) => {
        label: string
        value: string | null
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface biMemberAliasesLogicMeta {
    key: string
    __keaTypeGenInternalSelectorTypes: {
        query: (field: BIField | null, config: BIConfig, worksheet: BIVisualizationNode) => HogQLQuery | null
    }
}

export type biMemberAliasesLogicType = MakeLogicType<
    biMemberAliasesLogicValues,
    biMemberAliasesLogicActions,
    BIMemberAliasesProps,
    biMemberAliasesLogicMeta
>
export const biMemberAliasesLogic = kea<biMemberAliasesLogicType>([
    props({} as BIMemberAliasesProps),
    key(({ tabId }) => tabId),
    path((key) => ['products', 'business_intelligence', 'biMemberAliasesLogic', key]),
    actions({
        edit: (field: BIField, aliases: { value: string | null; label: string }[]) => ({ field, aliases }),
        setAlias: (value: string | null, label: string) => ({ value, label }),
        close: true,
        save: true,
    }),
    reducers({
        field: [null as BIField | null, { edit: (_, { field }) => field, close: () => null }],
        draft: [
            [] as { value: string | null; label: string }[],
            {
                edit: (_, { aliases }) => aliases,
                setAlias: (draft, { value, label }) => [
                    ...draft.filter((alias) => alias.value !== value),
                    { value, label },
                ],
            },
        ],
    }),
    selectors(({ props }) => ({
        query: [
            (s) => [s.field, biEditorLogic(props).selectors.config, biSceneLogic(props).selectors.worksheet],
            (field: BIField | null, config: BIConfig, worksheet: BIVisualizationNode): HogQLQuery | null => {
                const query = field
                    ? buildBIFilterOptionsQuery(
                          { ...config, filters: [{ field, operator: 'in', value: '' }], rowFilterGroup: undefined },
                          0
                      )
                    : null
                return query ? { ...query, variables: worksheet.source.variables } : null
            },
        ],
    })),
    listeners(({ props, values, actions }) => ({
        save: () => {
            if (!values.field) {
                return
            }
            const editor = biEditorLogic(props)
            const field = values.field
            const aliases = values.draft
                .filter((alias) => alias.label.trim())
                .map((alias) => ({ ...alias, label: alias.label.trim() }))
            editor.actions.restoreState({
                editorView: BIEditorView.BI,
                config: {
                    ...editor.values.config,
                    memberAliases: [
                        ...(editor.values.config.memberAliases ?? []).filter(
                            (entry) => biMemberFieldKey(entry.field) !== biMemberFieldKey(field)
                        ),
                        ...(aliases.length ? [{ field, aliases }] : []),
                    ],
                },
            })
            biSceneLogic(props).actions.recordWorksheet()
            editor.actions.runAfterChange()
            actions.close()
        },
    })),
])
